def image(name,alt,cls='',eager=False):
 return f'<img class="{cls}" src="/assets/{name}.webp" alt="{alt}" loading="{"eager" if eager else "lazy"}" decoding="async" width="1600" height="1067">'
def loading_intro():
 return '<div class="site-loader" aria-label="Opening Saanjh"><div class="loader-panel"></div><div class="loader-panel"></div><div class="loader-identity"><div class="loader-name" aria-label="Saanjh">'+''.join(f'<span aria-hidden="true" style="--letter:{i}">{c}</span>' for i,c in enumerate('saanjh'))+'</div><p>From first thought to final farewell</p><span class="loader-rule" aria-hidden="true"></span></div><button class="loader-skip" type="button">Skip intro</button></div>'
def head(title,desc,theme='',include_map=False):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{desc}"><meta name="theme-color" content="#481c2a"><title>{title}</title><script>try {{if ((location.pathname==='/' || location.pathname==='/index.html') && !location.hash && !matchMedia('(prefers-reduced-motion: reduce)').matches && !sessionStorage.getItem('saanjh-intro-seen-v2')) {{document.documentElement.classList.add('loading-intro');window.__saanjhIntroStarted=performance.now();window.__saanjhIntroFallback=setTimeout(function(){{document.documentElement.classList.remove('loading-intro','intro-leaving');}},8000);}}}} catch (e) {{}}</script><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/motion.css">{('<link rel="stylesheet" href="/assets/leaflet.css">' if include_map else '')}</head><body {theme}><a class="skip" href="#main">Skip to content</a>'''
def nav():
 return '''<header class="nav"><a class="brand" href="/" aria-label="Saanjh home">saanjh<span>Wedding atelier</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu</button><nav class="navlinks" id="navigation" aria-label="Main navigation"><a href="/#weekend">The weekend</a><a href="/#stories">Our stories</a><a href="/#destinations">Destinations</a><a class="enquire" href="/#brief">Begin your story</a></nav></header>'''
def footer(include_map=False):
 map_scripts='<script src="/assets/leaflet.js"></script><script src="/assets/world-map.js"></script>' if include_map else ''
 return '''<footer class="footer"><div class="footer-top"><a class="brand" href="/">saanjh</a><p>From the first thought<br>to the final farewell.</p></div><div class="footer-bottom"><span>© 2026 Saanjh · A wedding planner concept by Copywrk</span><span>Sample stories & figures · Illustrative stock photography</span><a href="/credits/">Image credits</a></div></footer>''' + map_scripts + '<script src="/app.js"></script></body></html>'
